          <Card
            key={index}
            className={`p-4 cursor-pointer transition-all hover-elevate ${
              selectedIndex === index ? "border-primary bg-accent" : ""
            } ${
              submitted && index === question.raspunsCorect
                ? "border-success bg-success/10"
                : ""
