              : "Incorect. Răspunsul corect este evidențiat."
          }
        />
      )}

      {!submitted && (
        <Button
          onClick={handleSubmit}
          disabled={selectedIndex === null}
          className="w-full"
          data-testid="button-submit"
        >
          Verifică răspunsul
        </Button>
      )}
    </div>
  );
}

